/**
 * 曲终横幅 RhythmGameComboResult（level56 GO 370 下 Root/Root-AllPerfect、Root-FullCombo、Root-Clear、Root-Finish）。
 * 动画 = sharedassets56 AnimationClip #99/#102/#100/#101（各 4 s）StreamedClip 逐键解码：
 * 段内 v = a·u³ + b·u² + c·u + d，u = t − 键时刻；常量绑定写成 t=0 单键。
 * UI 树取 RectTransform / Image / GradientColor 序列化值（1920×1080，全部中心锚点）。
 * 发射器取 level56 ParticleSystem / ParticleSystemRenderer 原值。
 * 由 scripts/gen-combo-result-clip.py 生成，勿手改。
 */
export type BannerKey = readonly [t: number, a: number, b: number, c: number, d: number];
export type Range = readonly [min: number, max: number];
export interface BannerNode {
  path: string; parent: number; active: boolean;
  x: number; y: number; w: number; h: number; sx: number; sy: number; rot: number;
  sprite?: string; rgba?: readonly [number, number, number, number];
  gradL?: readonly [number, number, number, number]; gradR?: readonly [number, number, number, number];
}
export interface BannerCurve { path: string; prop: string; keys: readonly BannerKey[] }
export interface BannerEmitter {
  path: string; tex: string; delay: Range; count: number; burstT: number; cycles: number; interval: number;
  life: Range; speed: Range; size: Range; sizeY: Range | null; color: readonly [number, number, number, number];
  shape: 'circle' | 'box'; box: Range | null;
  radius: number; thickness: number; rotSpeed: Range | null; limit: Range | null; dampen: number;
  sizeKeys: readonly (readonly [t: number, v: number, inSlope: number, outSlope: number])[] | null;
  grad: readonly [cols: readonly (readonly [t: number, r: number, g: number, b: number])[], alps: readonly (readonly [t: number, a: number])[]] | null;
  underCanvas: boolean; sort: number; maxSize: number;
}
export const COMBO_RESULT_CLIP_DURATION = 4;
/** 全屏黑罩 Bg 的 Image.color（四档共用）。 */
export const COMBO_RESULT_BG = [0, 0, 0, 0.6980392336845398] as const;
export interface BannerClip { index: number; root: string; clip: string; nodes: readonly BannerNode[]; curves: readonly BannerCurve[]; emitters: readonly BannerEmitter[] }
